<?php authorizeAdmin($u); $editing=!empty($_GET['id'])?row('SELECT * FROM users WHERE id=?',[(int)$_GET['id']]):null; $data=$_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='user'?$_POST:($editing??[]); $dataRoles=is_array($data['roles']??null)?$data['roles']:json_decode($data['roles']??'[]',true); $people=rows('SELECT u.*,d.name department FROM users u JOIN departments d ON d.id=u.department_id ORDER BY name'); ?>
<p class="page-intro">Mantén actualizados los datos y jefes inmediatos. Los cambios de responsables se aplican a las etapas pendientes y quedan en el historial.</p><section class="panel"><div class="panel-header"><h2>Directorio de funcionarios</h2><a class="text-link" href="/?page=import">Importar desde Excel →</a></div><div class="table-wrap"><table><thead><tr><th>Funcionario</th><th>Cargo / dependencia</th><th>Roles</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($people as $p): ?><tr><td><strong><?=e($p['name'])?></strong><small><?=e($p['identification'].' · '.$p['username'])?></small></td><td><?=e($p['job_title'])?><small><?=e($p['department'])?></small></td><td><?=e(implode(', ',array_map(fn($role)=>['admin'=>'Talento Humano','manager'=>'Jefe inmediato','subsecretary'=>'Subsecretario','mayor'=>'Alcalde'][$role],roles($p)))?:'Solicitante')?></td><td><?=(int)$p['active']?'Activo':'Inactivo'?></td><td><a class="text-link" href="/?page=users&id=<?=(int)$p['id']?>#user-form">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="detail-columns"><section class="panel form-panel" id="user-form"><h2><?=$editing?'Editar funcionario':'Nuevo funcionario'?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="user"><input type="hidden" name="id" value="<?=e($editing['id']??'')?>"><div class="form-grid"><?php foreach(['name'=>'Nombre completo','identification'=>'Cédula','username'=>'Usuario','email'=>'Correo electrónico','job_title'=>'Cargo','code'=>'Código','grade'=>'Grado'] as $key=>$label): ?><label><?=e($label)?><input name="<?=$key?>" value="<?=e($data[$key]??'')?>" <?=in_array($key,['code','grade'])?'':'required'?> <?=$key==='email'?'type="email"':''?> maxlength="180"></label><?php endforeach; ?><label>Vinculación<select name="appointment_type"><?php foreach(['Carrera administrativa','Libre nombramiento y remoción','Provisional','Trabajador oficial'] as $v): ?><option <?=($data['appointment_type']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach; ?></select></label><label>Dependencia<select name="department_id" required><?php foreach(rows('SELECT * FROM departments ORDER BY name') as $d): ?><option value="<?=$d['id']?>" <?=(int)($data['department_id']??0)===(int)$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach; ?></select></label><?php foreach(['manager_id'=>'Jefe inmediato','deputy_manager_id'=>'Suplente para evitar autoaprobación'] as $key=>$label): ?><label><?=e($label)?><select name="<?=$key?>"><option value="">Sin asignar</option><?php foreach($people as $p): if(!hasRole($p,'manager')||!(int)$p['active'])continue; ?><option value="<?=$p['id']?>" <?=(int)($data[$key]??0)===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach; ?></select></label><?php endforeach; ?><label>Clasificación de alto rango<select name="high_rank"><?php foreach([''=>'No aplica','Asesor de Despacho'=>'Asesor de Despacho','Secretario de Despacho'=>'Secretario de Despacho','Jefe de Oficina'=>'Jefe de Oficina'] as $v=>$l): ?><option value="<?=e($v)?>" <?=($data['high_rank']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach; ?></select></label><label>Estado<select name="active"><option value="1">Activo</option><option value="0" <?=(isset($data['active']) && !(int)$data['active'])?'selected':''?>>Inactivo</option></select></label><?php if(!$editing): ?><label>Contraseña inicial<input name="initial_password" type="password" required minlength="12" autocomplete="new-password"><small>El funcionario deberá cambiarla al ingresar.</small></label><?php endif; ?></div><fieldset><legend>Roles adicionales al de solicitante</legend><div class="checks"><?php foreach(['admin'=>'Administrador de Talento Humano','manager'=>'Jefe inmediato','subsecretary'=>'Subsecretario','mayor'=>'Alcalde'] as $v=>$l): ?><label><input type="checkbox" name="roles[]" value="<?=$v?>" <?=in_array($v,$dataRoles,true)?'checked':''?>> <?=e($l)?></label><?php endforeach; ?></div></fieldset><button class="button">Guardar funcionario</button></form></section>
<aside><section class="panel form-panel"><h2>Nueva dependencia</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="department"><label>Nombre<input name="name" required maxlength="180"></label><button class="button secondary">Crear dependencia</button></form></section><?php if($editing): ?><section class="panel form-panel"><h2>Restablecer acceso</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="id" value="<?=(int)$editing['id']?>"><label>Nueva contraseña temporal<input name="initial_password" type="password" required minlength="12" autocomplete="new-password"></label><button class="button secondary">Restablecer contraseña</button></form></section><?php endif; ?></aside></div>
